from collections import deque

class Solution:
    def minimumTime(self, n: int, edges: List[List[int]], disappear: List[int]) -> List[int]:
        INF = float('inf')
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))
        dist = [INF] * n
        dist[0] = 0
        q = deque([0])
        while q:
            u = q.popleft()
            du = dist[u]
            if du >= disappear[u]:
                continue
            for v, w in adj[u]:
                nd = du + w
                if nd < dist[v] and nd < disappear[v]:
                    dist[v] = nd
                    q.append(v)
        return [d if d < disappear[i] else -1 for i, d in enumerate(dist)]

