var minimumTime = function(n, edges, disappear) {
    const INF = Infinity;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }
    const dist = Array(n).fill(INF);
    dist[0] = 0;
    const heap = [[0, 0]];
    const push = (x) => { heap.push(x); let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1;
            if (heap[p][0] <= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } };
    const pop = () => { const t = heap[0], l = heap.pop();
        if (heap.length) { heap[0] = l; let i = 0;
            while (true) { let s = i, a = 2*i+1, b = 2*i+2;
                if (a < heap.length && heap[a][0] < heap[s][0]) s = a;
                if (b < heap.length && heap[b][0] < heap[s][0]) s = b;
                if (s === i) break;
                [heap[s], heap[i]] = [heap[i], heap[s]]; i = s; } }
        return t; };
    push([0, 0]);
    while (heap.length) {
        const [d, u] = pop();
        if (d > dist[u]) continue;
        for (const [v, w] of adj[u]) {
            const nd = d + w;
            if (nd < dist[v] && nd < disappear[v]) {
                dist[v] = nd;
                push([nd, v]);
            }
        }
    }
    return dist.map((d, i) => d < disappear[i] ? d : -1);
};
